service AdminShell {
  // Open an interactive shell session. The client streams commands and the
  // server streams back the output produced by those commands.
  rpc Shell(stream ShellInput) returns (stream ShellOutput) {}
}

// A single message sent by the client on the shell stream.
message ShellInput {
  oneof input {
    // A command line to be executed by the shell.
    string command = 1;
    // Signal that the client wants to terminate the session.
    Eof eof = 2;
  }
}

// Marker message used to signal the end of the client input.
