fn verify_admin_shell() {
    let server = PathBuf::from(std::env!("CARGO_MANIFEST_DIR"))
        .parent()
        .unwrap()
        .join("libsql-server");

    let iface_files = &[server.join("proto/admin_shell.proto")];
    let dirs = &[server.join("proto")];
    let out_dir = server.join("src").join("generated");

    let config = prost_build::Config::new();

    tonic_build::configure()
        .build_client(true)
        .build_server(true)
        .build_transport(true)
        .out_dir(&out_dir)
        .compile_with_config(config, iface_files, dirs)
        .unwrap();

    let status = Command::new("git")
        .arg("diff")
        .arg("--exit-code")
        .arg("--")
        .arg(&out_dir)
        .status()
        .unwrap();

    assert!(status.success(), "You should commit the protobuf files");
}
